<?php
use Illuminate\Http\Request; use Illuminate\Http\Response; use Illuminate\Support\Facades\DB; use Illuminate\Support\Facades\Route;
Route::match(['get','post'],'/',function(Request $request){ $message=''; if($request->isMethod('post')) { $u=$request->input('username',''); $p=$request->input('password',''); $sql="SELECT * FROM users WHERE username='$u' AND password='$p' LIMIT 1"; try { $user=DB::select($sql); $message=$user ? 'Login successful. FLAG: '.DB::table('secret_flag')->value('flag') : 'Invalid credentials'; } catch(Throwable $e) { $message='SQLite error: '.$e->getMessage(); } return new Response("<h1>Laravel auth-bypass SQLi</h1><p>Query: <code>$sql</code></p><p>$message</p>"); } return new Response('<h1>Laravel auth-bypass SQLi</h1><form method="post"><input name="username"><input name="password"><button>Login</button></form>'); });
